CREATE POLICY report_author_create_read ON public.staff_reports FOR SELECT TO authenticated USING(author_id=auth.uid() AND public.assistant_can(owner_id,'notes_create') AND public.can_access_branch_data(owner_id,business_id,branch_id));
CREATE POLICY snapshots_update_permission ON public.inventory_snapshots AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.assistant_can(owner_id,'inventory_snapshot_create')) WITH CHECK(public.assistant_can(owner_id,'inventory_snapshot_create'));
CREATE FUNCTION public.validate_stock_rule_scope() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.business_id IS DISTINCT FROM OLD.business_id OR NEW.branch_id IS DISTINCT FROM OLD.branch_id OR NEW.product_id IS DISTINCT FROM OLD.product_id) THEN RAISE EXCEPTION 'Huwezi kubadili eneo la sheria' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_stock_rule_scope BEFORE UPDATE ON public.stock_order_rules FOR EACH ROW EXECUTE FUNCTION public.validate_stock_rule_scope();